param([string[]]$CaseIds=@('C02','C03','C04','C06','C07','C09'),[int]$Trials=1,[int]$WarmRepeats=1,[string]$Label='smoke-six')
$ErrorActionPreference='Stop'
$base=$PSScriptRoot;$snapshot=Get-Content (Join-Path $base 'latest-inputs.txt');$matrix=Get-Content (Join-Path $base 'matrix.json') -Raw|ConvertFrom-Json
$selected=@($matrix.cases|Where-Object {$_.id -in $CaseIds});if($selected.Count -eq 0){throw 'No selected cases'}
$run=Join-Path $base ('runs/'+$Label+'-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss'));New-Item -ItemType Directory -Path $run -Force|Out-Null;Set-Content (Join-Path $base 'latest-run.txt') $run
Copy-Item (Join-Path $base 'matrix.json') (Join-Path $run 'matrix.json')
$records=@();$number=0
foreach($case in $selected){foreach($mode in @('auto','invoke')){if($mode -eq 'auto' -and !$case.automaticDotApplicable){continue};foreach($trial in 0..($Trials-1)){foreach($side in $(if($trial%2 -eq 0){@('a','b')}else{@('b','a')})){
$number++;if((Get-FileHash -LiteralPath $case.source -Algorithm SHA256).Hash -ne $case.sourceSha256){throw 'Corpus drift'}
$job=Join-Path $run ($case.id+'-'+$mode+'-'+$side+'-'+$trial);New-Item -ItemType Directory -Path $job|Out-Null
$psi=[Diagnostics.ProcessStartInfo]::new();$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.WorkingDirectory=$job;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
if($side -eq 'a'){$psi.FileName='dotnet';$psi.ArgumentList.Add((Join-Path $base 'worker-a/bin/Release/net9.0/WorkerA.dll'))}else{$psi.FileName=Join-Path $base 'worker-b/WorkerB.exe'}
foreach($arg in @($snapshot,$case.source,[string]$case.caretUtf16,$mode,[string]$WarmRepeats,(Join-Path $job 'result.json'),$(if($case.syntaxBoundaryCompile){'compile'}else{'no-compile'}))){$psi.ArgumentList.Add($arg)}
$watch=[Diagnostics.Stopwatch]::StartNew();$p=[Diagnostics.Process]::Start($psi);$out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync();$done=$p.WaitForExit(45000);if(!$done){$p.Kill($true);$p.WaitForExit(5000)|Out-Null};[IO.File]::WriteAllText((Join-Path $job 'stdout.log'),$out.GetAwaiter().GetResult());[IO.File]::WriteAllText((Join-Path $job 'stderr.log'),$err.GetAwaiter().GetResult());$watch.Stop()
$status='blocked-runtime';$missing=@();$unexpected=@();$queries=@();$valid=$false;$refMatch=$false;$detail='';$resultPath=Join-Path $job 'result.json'
if(Test-Path $resultPath){$data=Get-Content $resultPath -Raw|ConvertFrom-Json;$queries=@($data.queries);$requested=@($data.references|ForEach-Object {$_.path});$expected=@(Get-Content (Join-Path $snapshot 'references.json') -Raw|ConvertFrom-Json);$refMatch=($requested.Count -eq 4 -and (($requested -join '|') -eq ($expected -join '|')));$valid=$done -and $p.ExitCode -eq 0 -and $data.success -and $data.sourceSha256 -eq $case.sourceSha256 -and $data.caretUtf16 -eq $case.caretUtf16 -and $refMatch -and $queries.Count -eq ($WarmRepeats+1)
if($valid){foreach($q in $queries){foreach($name in $case.expected){if($name -cnotin @($q.names)){$missing+=[ordered]@{iteration=$q.iteration;name=$name}}};foreach($name in $case.absent){if($name -cin @($q.names)){$unexpected+=[ordered]@{iteration=$q.iteration;name=$name}}}};$status=if($data.automaticSuppressionEligible -eq $true){'protocol-suppressed'}elseif($case.group -eq 'trigger-protocol' -and $mode -eq 'auto' -and ($missing.Count -or $unexpected.Count)){'protocol-observed-no-candidates'}elseif($missing.Count -or $unexpected.Count){'candidate-expectation-not-met'}else{'passed'}}else{$detail=$data.stage+': '+$data.error}}
$row=[ordered]@{number=$number;case=$case.id;category=$case.category;group=$case.group;mode=$mode;side=$side;trial=$trial;status=$status;validInvocation=$valid;sameRequestedRefs=$refMatch;missing=$missing;unexpected=$unexpected;firstQueryMs=$(if($queries.Count){$queries[0].ms}else{$null});repeatQueryMs=@($queries|Select-Object -Skip 1|ForEach-Object {$_.ms});rawCounts=@($queries|ForEach-Object {$_.count});pid=$p.Id;exitCode=$p.ExitCode;timedOut=(!$done);exited=$p.HasExited;wallMs=$watch.Elapsed.TotalMilliseconds;result=$resultPath;detail=$detail};$records+=$row;$records|ConvertTo-Json -Depth 9|Set-Content (Join-Path $run 'progress.json');Write-Output ($case.id+' '+$mode+' '+$side+' '+$trial+' '+$status+' first='+$row.firstQueryMs+' counts='+($row.rawCounts -join ','))
}}}}
[ordered]@{label=$Label;run=$run;sourceMatrix=(Join-Path $base 'matrix.json');snapshot=$snapshot;trials=$Trials;repeatedQueries=$WarmRepeats;rows=$records;counts=@($records|Group-Object { $_.status }|Select-Object Name,Count);noVmUI=$true;noProductModification=$true}|ConvertTo-Json -Depth 11|Set-Content (Join-Path $run 'summary.json')
